sys_script_include.script:
var BaseUtils = Class.create();
BaseUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

   checkDuplicateManager: function() {
        // Pega os parâmetros enviados pelo Client Script
        var managerSysId = this.getParameter('sysparm_manager_sysid');
        var currentBaseSysId = this.getParameter('sysparm_current_base_sysid');

        // Se o campo gerente estiver vazio, não faz nada (é válido)
        if (!managerSysId) {
            return 'false';
        }

        // ATENÇÃO: Verifique se este é o nome da sua tabela 'Base'
        var grBase = new GlideRecord('x_1836079_office_base'); 

        // ATENÇÃO: Verifique se este é o nome do seu campo 'manager base'
        grBase.addQuery('manager_base', managerSysId); 

        // Ignora a base que estamos editando no momento
        if (currentBaseSysId) {
            grBase.addQuery('sys_id', '!=', currentBaseSysId);
        }
        grBase.query();

        if (grBase.next()) {
            return 'true'; // Encontrou duplicado!
        } else {
            return 'false'; // Não encontrou (é válido).
        }
    },

    type: 'BaseUtils'
});
